import React, { useMemo, useState } from 'react';
import {
  useGetReturnSalesOrderByIdQuery,
  useGetUserQuery,
  useNewSalesReturnMutation,
} from '../posApi';
import {
  Box,
  Button,
  Grid,
  InputAdornment,
  TextField,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Divider,
  CircularProgress,
  Stack,
} from '@mui/material';
import { appColors } from '../../theme/appColors';
import SearchIcon from '@mui/icons-material/Search';
import { useTranslation } from 'react-i18next';
import { useFormik } from 'formik';
import { IUserInfo } from '../../core/Interface/user.interface';
import TopInfoSkeleton from '../Dashboard/TopInfoSkeleton';
import { formatDateTime, getPriceFormat } from '../../core/utils';
import { useNotifier } from '../../core/Notifier';
import AnimatedPage from '../../layouts/AnimatedPage';
import { useParams } from 'react-router-dom';
import { ISaleReturnData } from '../../core/Interface/saleReturn.interface';

const ReturnSales = () => {
  const { invoiceId: navInvoiceId } = useParams<{ invoiceId?: string }>();

  const [invoiceId, setInvoiceId] = useState<string>(navInvoiceId || '');
  const { data, isLoading, isError } = useGetReturnSalesOrderByIdQuery(
    invoiceId.split('_')[0],
    {
      skip: !invoiceId,
    }
  );
  const { t } = useTranslation(['common', 'return']);
  const { showErrorMessage, showMessage } = useNotifier();

  const returnSalesList = useMemo<ISaleReturnData | undefined>(() => {
    return data?.data as ISaleReturnData;
  }, [data?.data]);

  const [newSalesReturn, { isLoading: isSubmitting }] =
    useNewSalesReturnMutation();
  const [returnQuantities, setReturnQuantities] = useState<{
    [productId: string]: number;
  }>({});
  const [showContent, setShowContent] = useState(true);

  const handleReturnQtyChange = (productId: string, value: number) => {
    setReturnQuantities((prevQuantities) => ({
      ...prevQuantities,
      [productId]: value,
    }));
  };

  const { data: companyData } = useGetUserQuery();

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) {
        return userData.company.currencyCode;
      }
    }
    return '';
  }, [companyData]);

  const handleSubmit = async () => {
    try {
      const commonSalesId = returnSalesList?.items[0]?.salesId;

      const isValid = returnSalesList?.items?.every((item) => {
        const returnQty = returnQuantities[item.productId] || 0;
        return returnQty >= 0 && returnQty <= item.qty;
      });

      if (!isValid) {
        showErrorMessage('Invalid return quantities');
        return;
      }

      const temData = {
        dateTime: returnSalesList?.sale.dateTime,
        saleId: commonSalesId,
        items: returnSalesList?.items?.map((item) => ({
          productId: item.productId,
          returnQty: returnQuantities[item.productId] || 0,
        })),
      };

      const returnResponse = await newSalesReturn(temData).unwrap();
      if (!returnResponse.status) {
        showErrorMessage(returnResponse.message);
      } else {
        showMessage(returnResponse.message);
        setShowContent(false);
        formik.resetForm();
        setInvoiceId('');
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };
  const formik = useFormik({
    initialValues: {
      invoiceId: '',
    },
    onSubmit: async (values) => {
      try {
        setInvoiceId(values.invoiceId);
      } catch (error) {
        showErrorMessage('Something went wrong');
      }
    },
  });

  return isLoading ? (
    <AnimatedPage>
      <Stack
        alignItems="center"
        sx={{ top: '50%', left: '50%', position: 'absolute' }}
      >
        <CircularProgress />
      </Stack>
    </AnimatedPage>
  ) : (
    <AnimatedPage>
      <Box data-testid="salesReturn">
        <Box sx={{ py: 2 }}>
          <Grid
            container
            display="flex"
            justifyContent="flex-end"
            key={6}
          >
            <form noValidate onSubmit={formik.handleSubmit}>
              <Box
                alignItems="center"
                display="flex"
              >
                <TextField
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <SearchIcon />
                      </InputAdornment>
                    ),
                  }}
                  autoComplete="off"
                  name="invoiceId"
                  onChange={formik.handleChange}
                  placeholder="Invoice ID..."
                  size="small"
                  sx={{
                    mr: 5,
                    mb: 0,
                    marginTop: '20px',
                    '& .MuiFormLabel-root.MuiInputLabel-root': {
                      color: appColors.darkGray[20],
                    },
                    width: 300,
                  }}
                  type="text"
                  value={formik.values.invoiceId}
                  variant="outlined"
                />
                <Button
                  sx={{
                    mr: 2,
                    mb: 0,
                    width: 130,
                    border: 'none',
                    backgroundColor: appColors.darkGreen[20],
                    marginTop: '20px',
                    borderRadius: '8px',
                    cursor: 'pointer',
                    height: '42px',
                    fontWeight: 'bold',
                    '&:hover': {
                      backgroundColor: appColors.greyishBlue[20],
                    },
                  }}
                  type="submit"
                  variant="outlined"
                >
                  {t('common:search')}
                </Button>
              </Box>
            </form>
          </Grid>
        </Box>

        {!isLoading && !isError && returnSalesList && showContent && (
          <Grid>
            <Box
              sx={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
              }}
            >
              <Box sx={{ height: '20px' }} />
              <Divider
                flexItem
                orientation="horizontal"
              />
              <Grid
                container
                spacing={2}
              >
                <Grid
                  item
                  xs={6}
                >
                  <Box sx={{ mt: '15px', mb: '15px' }}>
                    <Typography variant="body1">
                      <strong>{t('return:invoiceId')} :</strong>{' '}
                      {returnSalesList?.sale?.invoiceId !== undefined
                        ? returnSalesList?.sale?.invoiceId
                        : ''}
                    </Typography>
                    <Typography variant="body1">
                      <strong>Mobile :</strong> {returnSalesList?.sale?.mobile}
                    </Typography>
                  </Box>
                </Grid>
                <Grid
                  item
                  xs={6}
                >
                  <Box sx={{ mt: '15px', mb: '15px', textAlign: 'right' }}>
                    <Typography variant="body1">
                      {/* <strong>Date :</strong> */}
                      {returnSalesList?.sale?.dateTime
                        ? formatDateTime(
                            new Date(returnSalesList?.sale?.dateTime)
                          )
                        : 'N/A'}
                    </Typography>
                  </Box>
                </Grid>
              </Grid>
              <Divider
                flexItem
                orientation="horizontal"
              />
            </Box>
            <TableContainer sx={{ overflowX: 'auto', width: '100%' }}>
              <Table sx={{ minWidth: 550 }}>
                <TableHead>
                  <TableRow>
                    <TableCell
                      align="left"
                      sx={{
                        fontSize: 20,
                      }}
                    >
                      {t('return:qty')}
                    </TableCell>
                    <TableCell
                      align="left"
                      sx={{
                        fontSize: 20,
                      }}
                    >
                      {t('return:returnQty')}
                    </TableCell>
                    <TableCell
                      sx={{
                        fontSize: 20,
                      }}
                    >
                      {t('return:description')}
                    </TableCell>
                    <TableCell
                      align="right"
                      sx={{
                        fontSize: 20,
                      }}
                    >
                      {t('return:unitPrice')}
                    </TableCell>
                    <TableCell
                      align="right"
                      sx={{
                        fontSize: 20,
                      }}
                    >
                      {t('return:discount')}
                    </TableCell>

                    <TableCell
                      align="right"
                      sx={{
                        fontSize: 20,
                      }}
                    >
                      {t('return:amount')}
                    </TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {returnSalesList &&
                    returnSalesList.items &&
                    returnSalesList.items.map((item, index) => (
                      <TableRow key={index}>
                        <TableCell
                          align="left"
                          sx={{
                            typography: 'body1',
                            borderBottom: 'none',
                          }}
                        >
                          {item.qty}
                        </TableCell>
                        <TableCell
                          align="left"
                          sx={{
                            typography: 'body1',
                            borderBottom: 'none',
                          }}
                        >
                          <TextField
                            autoComplete="off"
                            onChange={(e) =>
                              handleReturnQtyChange(
                                item.productId,
                                parseInt(e.target.value, 10)
                              )
                            }
                            size="small"
                            style={{ fontSize: '0.8rem', width: '100px' }}
                            type="number"
                            inputProps={{ step: 'any' }}
                            value={
                              returnQuantities[item.productId] !== undefined
                                ? returnQuantities[item.productId]
                                : 0
                            }
                          />
                        </TableCell>
                        <TableCell
                          sx={{
                            maxWidth: 100,
                            wordWrap: 'break-word',
                            typography: 'body1',
                            borderBottom: 'none',
                          }}
                        >
                          {item.productName}
                        </TableCell>
                        <TableCell
                          align="right"
                          sx={{
                            typography: 'body1',
                            borderBottom: 'none',
                          }}
                        >
                          {getPriceFormat(item.unitPrice, currencyCode)}
                        </TableCell>
                        <TableCell
                          align="right"
                          sx={{
                            typography: 'body1',
                            borderBottom: 'none',
                          }}
                        >
                          {item.isDiscountPercentage
                            ? item.discountValue + '%'
                            : getPriceFormat(item.discountValue, currencyCode)}
                        </TableCell>
                        <TableCell
                          align="right"
                          sx={{
                            typography: 'body1',
                            borderBottom: 'none',
                          }}
                        >
                          {getPriceFormat(item.amount, currencyCode)}
                        </TableCell>
                      </TableRow>
                    ))}
                </TableBody>
              </Table>
            </TableContainer>
            <Divider
              flexItem
              orientation="horizontal"
            />
            <Grid
              container
              spacing={2}
            >
              <Grid
                item
                xs={6}
              >
                <Box sx={{ mt: '10px', mb: '10px' }}>
                  <Typography fontSize={20}>{t('return:subTotal')} </Typography>
                  <Typography fontSize={20}>
                    {t('return:discount')}{' '}
                    {returnSalesList?.sale?.isDiscountPercentage
                      ? '( ' +
                        (returnSalesList?.sale?.discountValue || 0) +
                        '% )'
                      : ''}
                  </Typography>
                </Box>
              </Grid>
              <Grid
                item
                xs={6}
              >
                <Box sx={{ mt: '10px', mb: '10px', textAlign: 'right' }}>
                  <Typography fontSize={20}>
                    {returnSalesList?.sale?.subTotal !== undefined
                      ? getPriceFormat(
                          returnSalesList.sale.subTotal,
                          currencyCode
                        )
                      : 'N/A'}
                  </Typography>
                  <Typography fontSize={20}>
                    {returnSalesList?.sale?.discount !== undefined
                      ? getPriceFormat(
                          returnSalesList.sale.discount,
                          currencyCode
                        )
                      : 'N/A'}
                  </Typography>
                </Box>
              </Grid>
            </Grid>
            <Divider
              flexItem
              orientation="horizontal"
              sx={{ border: '1px dashed #E0E0E0' }}
            />
            <Grid
              container
              spacing={2}
            >
              <Grid
                item
                xs={6}
              >
                <Box sx={{ mt: '10px', mb: '10px' }}>
                  <Typography fontSize={20}>{t('return:total')}</Typography>
                </Box>
              </Grid>
              <Grid
                item
                xs={6}
              >
                <Box sx={{ mt: '10px', mb: '10px', textAlign: 'right' }}>
                  <Typography fontSize={20}>
                    {returnSalesList?.sale?.total !== undefined
                      ? getPriceFormat(returnSalesList.sale.total, currencyCode)
                      : 'N/A'}
                  </Typography>
                </Box>
              </Grid>
              <Grid
                container
                justifyContent="flex-end"
              >
                <Grid
                  item
                  sx={{ textAlign: 'right' }}
                  xs={6}
                >
                  <Box sx={{ mt: '20px' }}>
                    <Button
                      autoFocus
                      disabled={isSubmitting}
                      onClick={handleSubmit}
                      sx={{
                        width: 200,
                        height: 42,
                        borderRadius: '5px',
                      }}
                      type="submit"
                      variant="contained"
                    >
                      {isSubmitting && (
                        <Box sx={{ pr: 2, pt: 0.5 }}>
                          <CircularProgress
                            size={16}
                            sx={{ color: 'white' }}
                          />
                        </Box>
                      )}
                      {t('common:submit')}
                    </Button>
                  </Box>
                </Grid>
              </Grid>
            </Grid>
          </Grid>
        )}
        {isLoading &&
          [1, 2, 3, 4].map((i) => (
            <Grid
              item
              key={i}
              xs={4}
            >
              <TopInfoSkeleton data-testid="top--skeleton" />
            </Grid>
          ))}
        {!isLoading &&
          isError &&
          returnSalesList &&
          returnSalesList.items &&
          returnSalesList.items.length === 0 && (
            <Typography
              align="center"
              data-testid="top-nodata"
              width="100%"
            >
              {t('common:noData')}
            </Typography>
          )}
      </Box>
    </AnimatedPage>
  );
};

export default ReturnSales;
